# use serde::{Deserialize, Serialize};
# use serde_with::skip_serializing_none;
#[skip_serializing_none]
# #[derive(Debug, Eq, PartialEq)]
#[derive(Deserialize, Serialize)]
struct Foo {
    a: Option<usize>,
    b: Option<usize>,
    c: Option<usize>,
    d: Option<usize>,
    e: Option<usize>,
    f: Option<usize>,
    g: Option<usize>,
}

