# */
#
impl TryFrom<u8> for Boollike {
    type Error = String;
    fn try_from(v: u8) -> Result<Self, Self::Error> {
        match v {
            0 => Ok(Boollike::False),
            1 => Ok(Boollike::True),
            _ => Err(format!("Boolikes can only be constructed from 0 or 1 but found {}", v))
        }
    }
}
