use sea_query::{extension::postgres::Type, *};

enum FontFamily {
    Type,
    Serif,
    Sans,
    Monospace,
}

impl Iden for FontFamily {
    fn unquoted(&self, s: &mut dyn Write) {
        write!(
            s,
            "{}",
            match self {
                Self::Type => "font_family",
                Self::Serif => "serif",
                Self::Sans => "sans",
                Self::Monospace => "monospace",
            }
        )
        .unwrap();
    }
}

