#[derive(Debug, PartialEq, Deserialize)]
struct Config {
    numbers: Vec<usize>,
    untyped: Map<String, usize>,
}

Jail::expect_with(|jail| {
    jail.create_file("Config.toml", r#"
        [global.untyped]
        global = 0
        hi = 7

        [staging]
        numbers = [1, 2, 3]

        [release]
        numbers = [6, 7, 8]
    "#)?;

    // Enable nesting via `nested()`.
