    assert_eq!(*c.number, 10);

    let tag = c.number.tag();
    let metadata = figment.get_metadata(tag).expect("number has tag");

    assert!(!tag.is_default());
    assert_eq!(metadata.name, "TOML file");
    Ok(())
});

